class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def splitListToParts(nums, k):
    head = build(nums)
    n = 0
    cur = head
    while cur:
        n += 1
        cur = cur.next
    base, extra = divmod(n, k)
    parts = []
    cur = head
    for i in range(k):
        size = base + (1 if i < extra else 0)
        part_head = cur
        for _ in range(size - 1):
            cur = cur.next
        if size > 0:
            nxt = cur.next
            cur.next = None
            cur = nxt
        parts.append(dump(part_head))
    return parts
